INSERT INTO TB_EEP_FEEDBACK_LOG (FB_SQ, LOG_CD, CONTENT, EMPLY_ID)
SELECT FB_SQ, 'COMMENT', #{CONTENT}, #{EMPLY_ID} FROM TB_EEP_FEEDBACK_M WHERE FB_SQ = #{FB_SQ} AND STATUS_CD NOT IN ('DONE', 'REJECT');
UPDATE TB_EEP_FEEDBACK_M SET STATUS_CD = 'NEW' WHERE FB_SQ = #{FB_SQ} AND STATUS_CD NOT IN ('DONE', 'REJECT')
